'use strict';
const $=(s,p=document)=>p.querySelector(s);
const $$=(s,p=document)=>[...p.querySelectorAll(s)];
const D=window.SK_DATA;
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brandFor=id=>D.brands.find(b=>b.id===id);
const vehicleFor=id=>D.vehicles.find(v=>v.id===id);
const money=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(value);
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const page=document.body.dataset.page;
function readStore(key,session=false){try{const value=JSON.parse((session?sessionStorage:localStorage).getItem(key)||'[]');return Array.isArray(value)?value.filter(id=>typeof id==='string'&&vehicleFor(id)):[];}catch(_){return [];}}
function writeStore(key,value,session=false){try{(session?sessionStorage:localStorage).setItem(key,JSON.stringify(value));}catch(_){}}
let savedIds=readStore('sk-universe-saved');
let compareIds=readStore('sk-universe-compare',true).slice(0,3);
let toastTimer;
function toast(message){const el=$('.toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}

const themeButton=$('.theme-switch');
function syncTheme(){const dark=document.documentElement.dataset.theme==='dark';themeButton.setAttribute('aria-pressed',String(dark));themeButton.setAttribute('aria-label',dark?'Switch to day theme':'Switch to night theme');$('meta[name="theme-color"]').content=dark?'#14192c':'#f7f7fc';}
themeButton.addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('sk-universe-theme',document.documentElement.dataset.theme);}catch(_){}syncTheme();});
syncTheme();
const navigation=$('.main-nav'),menuButton=$('.menu-toggle'),worldMenu=$('.world-menu');
function closeMenu(){navigation.classList.remove('is-open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open navigation');worldMenu.open=false;}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';navigation.classList.toggle('is-open',open);menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
$$('a',navigation).forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('click',event=>{if(!event.target.closest('.site-header'))closeMenu();});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();});

let carousel=null;
const allDialogs=$$('dialog');
function syncModalState(){const open=allDialogs.some(d=>d.open);document.body.classList.toggle('modal-open',open);carousel?.suspend('dialog',open);}
function openDialog(dialog){closeMenu();allDialogs.forEach(d=>{if(d!==dialog&&d.open)d.close();});if(!dialog.open)dialog.showModal();syncModalState();}
allDialogs.forEach(dialog=>{
 $('.dialog-close',dialog).addEventListener('click',()=>dialog.close());
 dialog.addEventListener('close',syncModalState);
 dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();});
});
$$('[data-open="credits"]').forEach(b=>b.addEventListener('click',()=>openDialog($('#credits-dialog'))));

function vehicleCard(v){const b=brandFor(v.brand);const saved=savedIds.includes(v.id),compared=compareIds.includes(v.id);return `<article class="vehicle-card" data-vehicle-id="${v.id}"><div class="vehicle-image"><button type="button" class="photo-vehicle" data-detail="${v.id}" aria-label="Explore ${escapeHTML(v.name)}"><img src="assets/${v.image}" alt="${escapeHTML(v.name+' · '+b.name+' brand imagery')}" loading="lazy" style="object-position:${v.position};object-fit:${['classic','supercargo'].includes(v.id)?'contain':'cover'}"></button><span class="brand-pill">${escapeHTML(b.name)}</span><button class="bookmark-button" type="button" data-save="${v.id}" aria-pressed="${saved}" aria-label="${saved?'Remove':'Save'} ${escapeHTML(v.name)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4Z"/></svg></button></div><div class="vehicle-card-copy"><div class="vehicle-tags"><span>${escapeHTML(v.category)}</span><span>${escapeHTML(v.energy)}</span></div><h3>${escapeHTML(v.name)}</h3><p>${escapeHTML(v.line)}</p><div class="vehicle-card-bottom"><label class="compare-check"><input type="checkbox" data-compare="${v.id}" ${compared?'checked':''}>Compare</label><button class="vehicle-detail-link" type="button" data-detail="${v.id}">Explore <span aria-hidden="true">↗</span></button></div></div></article>`;}
function syncSaved(){const badge=$('.saved-count');badge.textContent=savedIds.length;badge.hidden=!savedIds.length;$$('[data-save]').forEach(button=>{const saved=savedIds.includes(button.dataset.save);button.setAttribute('aria-pressed',String(saved));button.setAttribute('aria-label',`${saved?'Remove':'Save'} ${vehicleFor(button.dataset.save)?.name||'vehicle'}`);if(button.classList.contains('button'))button.innerHTML=(saved?'Saved in My Garage':'Save to My Garage')+' <span>✧</span>';});if(page==='saved')renderSaved();}
function syncCompare(){const tray=$('.compare-tray');tray.hidden=!compareIds.length;$('#compare-count').textContent=compareIds.length;$$('[data-compare]').forEach(input=>input.checked=compareIds.includes(input.dataset.compare));$('#compare-open').disabled=compareIds.length<2;$('#compare-open').setAttribute('aria-label',compareIds.length<2?'Select at least two vehicles to compare':'Compare selected vehicles');}
function toggleSave(id){if(!vehicleFor(id))return;const had=savedIds.includes(id);savedIds=had?savedIds.filter(x=>x!==id):[...savedIds,id];writeStore('sk-universe-saved',savedIds);syncSaved();toast(had?'Removed from My Garage.':'Saved to My Garage in this browser.');}
function setCompare(id,checked){if(!vehicleFor(id))return;if(checked&&!compareIds.includes(id)){if(compareIds.length===3){toast('You can compare up to three vehicles at a time.');syncCompare();return;}compareIds.push(id);}else if(!checked)compareIds=compareIds.filter(x=>x!==id);writeStore('sk-universe-compare',compareIds,true);syncCompare();}
function renderComparison(){if(compareIds.length<2){toast('Choose at least two vehicles to compare.');return;}const list=compareIds.map(vehicleFor);const cell=v=>`<th>${`<img src="assets/${v.image}" alt="${escapeHTML(v.name)}" style="object-position:${v.position};object-fit:${['classic','supercargo'].includes(v.id)?'contain':'cover'}">`}<strong>${escapeHTML(v.name)}</strong></th>`;const row=(label,get)=>`<tr><td>${label}</td>${list.map(v=>`<td>${get(v)}</td>`).join('')}</tr>`;$('#compare-content').innerHTML=`<table class="comparison-table"><thead><tr><th>Your shortlist</th>${list.map(cell).join('')}</tr></thead><tbody>${row('Brand',v=>escapeHTML(brandFor(v.brand).name))}${row('Category',v=>escapeHTML(v.category))}${row('Energy',v=>escapeHTML(v.energy))}${row('Availability',()=> 'Confirm with the showroom')}${row('Quotation',()=> 'Request from the showroom')}${row('Learn more',v=>`<a href="${v.url}" target="_blank" rel="noopener" class="text-link">Manufacturer website ↗</a>`)}${row('Your next step',v=>`<a class="button compact" href="book.html?type=test-ride&vehicle=${v.id}">Plan a conversation ↗</a>`)}</tbody></table><p class="fine-print" style="margin-top:20px">Compare the type of journey each vehicle serves. Exact variants, specifications, quotations and local availability are confirmed by the manufacturer and showroom.</p>`;openDialog($('#compare-dialog'));}
$('#compare-open').addEventListener('click',renderComparison);
$('#compare-clear').addEventListener('click',()=>{compareIds=[];writeStore('sk-universe-compare',compareIds,true);syncCompare();});
function showVehicle(id){const v=vehicleFor(id);if(!v)return;const b=brandFor(v.brand);$('#detail-content').innerHTML=`<div class="detail-hero"><img src="assets/${v.image}" alt="${escapeHTML(v.name+' brand imagery')}" style="object-position:${v.position};object-fit:${['classic','supercargo'].includes(v.id)?'contain':'cover'}"></div><div class="detail-copy"><p class="eyebrow">${escapeHTML(b.name.toUpperCase())} / THE COLLECTION</p><h2 id="detail-title">${escapeHTML(v.name)}</h2><div class="detail-tags"><span>${escapeHTML(v.category)}</span><span>${escapeHTML(v.energy)}</span></div><p>${escapeHTML(v.line)} Explore the official brand information, save this possibility or plan your next showroom conversation.</p><div class="detail-actions"><a href="book.html?type=test-ride&vehicle=${v.id}" class="button">Plan your next step <span>↗</span></a><a href="${v.url}" target="_blank" rel="noopener" class="text-link">Manufacturer information ↗</a><button class="button secondary" type="button" data-save="${v.id}" aria-pressed="${savedIds.includes(v.id)}">${savedIds.includes(v.id)?'Saved in My Garage':'Save to My Garage'} <span>✧</span></button></div><p class="detail-notice">Manufacturer imagery is illustrative. Ask the showroom to confirm the available variants, specifications, pricing and visiting arrangements.</p></div>`;openDialog($('#detail-dialog'));}
document.addEventListener('click',event=>{const save=event.target.closest('[data-save]');if(save){toggleSave(save.dataset.save);return;}const detail=event.target.closest('[data-detail]');if(detail){showVehicle(detail.dataset.detail);return;}const branch=event.target.closest('[data-branch-detail]');if(branch){showBranch(branch.dataset.branchDetail);return;}const gallery=event.target.closest('[data-gallery]');if(gallery){openPhoto(gallery.dataset.gallery);return;}});
document.addEventListener('change',event=>{if(event.target.matches('[data-compare]'))setCompare(event.target.dataset.compare,event.target.checked);});

function initCarousel(){const stage=$('.hero-showcase');if(!stage)return;const slides=$$('.hero-slide',stage),dots=$$('[data-slide]',stage),pause=$('.slide-pause',stage);let index=0,timer=null,paused=reducedMotion.matches;const stops=new Set(document.hidden?['hidden']:[]);function playback(){clearTimeout(timer);stage.classList.remove('is-playing');pause.setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow');pause.firstElementChild.textContent=paused?'▶':'Ⅱ';if(!paused&&!stops.size){void stage.offsetWidth;stage.classList.add('is-playing');timer=setTimeout(()=>go(index+1,false),7000);}}function suspend(reason,on){if(on)stops.add(reason);else stops.delete(reason);playback();}function go(next,announce=true){index=(next+slides.length)%slides.length;slides.forEach((slide,i)=>{slide.classList.toggle('is-active',i===index);slide.setAttribute('aria-hidden',String(i!==index));});dots.forEach((dot,i)=>dot.setAttribute('aria-pressed',String(i===index)));const s=slides[index];$('#slide-title').textContent=s.dataset.title;$('#slide-kicker').textContent=s.dataset.kicker;$('#hero-brand').textContent=s.dataset.brand;$('#hero-link').href=s.dataset.link;$('#slide-count').textContent=`${String(index+1).padStart(2,'0')} / ${String(slides.length).padStart(2,'0')}`;if(announce)$('#slide-status').textContent=`${index+1} of ${slides.length}: ${s.dataset.brand}. ${s.dataset.title}`;playback();}dots.forEach(dot=>dot.addEventListener('click',()=>go(Number(dot.dataset.slide))));$('.slide-prev',stage).addEventListener('click',()=>go(index-1));$('.slide-next',stage).addEventListener('click',()=>go(index+1));pause.addEventListener('click',()=>{paused=!paused;playback();});stage.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')suspend('hover',true);});stage.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse')suspend('hover',false);});stage.addEventListener('focusin',()=>suspend('focus',true));stage.addEventListener('focusout',e=>{if(!stage.contains(e.relatedTarget))suspend('focus',false);});stage.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();go(index+(e.key==='ArrowRight'?1:-1));}});document.addEventListener('visibilitychange',()=>suspend('hidden',document.hidden));reducedMotion.addEventListener('change',e=>{if(e.matches)paused=true;playback();});let touch=null;stage.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')touch=e.clientX;});stage.addEventListener('pointerup',e=>{if(e.pointerType==='touch'&&touch!==null){const dx=e.clientX-touch;if(Math.abs(dx)>60)go(index+(dx<0?1:-1));touch=null;}});stage.addEventListener('pointercancel',()=>touch=null);go(0,false);return {suspend};}
carousel=initCarousel();

let photoIndex=0;
const galleryPhotos=D.gallery||[];
function displayPhoto(index){if(!galleryPhotos.length)return;photoIndex=(index+galleryPhotos.length)%galleryPhotos.length;const p=galleryPhotos[photoIndex];$('#photo-image').src=p.src;$('#photo-image').alt=p.alt;$('#photo-title').textContent=p.title;$('#photo-credit').textContent=p.credit;$('#photo-count').textContent=`${String(photoIndex+1).padStart(2,'0')} / ${String(galleryPhotos.length).padStart(2,'0')}`;}
function openPhoto(name){const i=galleryPhotos.findIndex(p=>p.src===`assets/${name}`);if(i<0)return;displayPhoto(i);openDialog($('#photo-dialog'));}
$('#photo-prev').addEventListener('click',()=>displayPhoto(photoIndex-1));$('#photo-next').addEventListener('click',()=>displayPhoto(photoIndex+1));$('#photo-dialog').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();displayPhoto(photoIndex+(e.key==='ArrowRight'?1:-1));}});

function initCatalog(){const grid=$('#vehicle-grid');if(!grid)return;let category='all';const search=$('#vehicle-search'),brand=$('#brand-filter'),energy=$('#energy-filter'),sort=$('#vehicle-sort');const params=new URLSearchParams(location.search);if(brandFor(params.get('brand')))brand.value=params.get('brand');function render(){const q=search.value.trim().toLowerCase();let list=D.vehicles.filter(v=>(brand.value==='all'||v.brand===brand.value)&&(energy.value==='all'||v.energy===energy.value)&&(`${v.name} ${brandFor(v.brand).name} ${v.category}`.toLowerCase().includes(q))&&(category==='all'||category==='riding'&&['royal','tvs','yamaha'].includes(v.brand)||category==='electric'&&v.energy==='Electric'||category==='business'&&['montra','ashok'].includes(v.brand)));if(sort.value==='az')list.sort((a,b)=>a.name.localeCompare(b.name));if(sort.value==='za')list.sort((a,b)=>b.name.localeCompare(a.name));grid.innerHTML=list.map(vehicleCard).join('');$('#vehicle-result-count').textContent=`${list.length} ${list.length===1?'possibility':'possibilities'} to explore`;$('#vehicle-empty').hidden=!!list.length;syncCompare();}search.addEventListener('input',render);[brand,energy,sort].forEach(e=>e.addEventListener('change',render));$$('[data-category]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.category;$$('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));render();}));$('#reset-filters').addEventListener('click',()=>{search.value='';brand.value='all';energy.value='all';sort.value='featured';category='all';$$('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category==='all')));render();});render();}
function initBrand(){if(!$('#brand-hero'))return;const params=new URLSearchParams(location.search);let id=brandFor(params.get('brand'))?params.get('brand'):'royal';function render(next){id=next;const b=brandFor(id);$('#brand-hero').innerHTML=`<img src="assets/${b.image}" alt="${escapeHTML(b.name+' brand imagery')}" fetchpriority="high"><div class="masthead-shade"></div><div class="section-shell masthead-copy"><p class="eyebrow">OUR WORLD / ${escapeHTML(b.category.toUpperCase())}</p><h1>${escapeHTML(b.line)}</h1><p>${escapeHTML(b.name)} · A world of possibilities.</p></div><span class="masthead-orbit" aria-hidden="true">✧</span>`;$('#brand-copy').innerHTML=`<p class="eyebrow">${escapeHTML(b.name.toUpperCase())}</p><h2>Where will your<br>next chapter begin?</h2><p>${escapeHTML(b.description)}</p><a class="button" href="book.html?type=enquiry&brand=${b.id}">Start a conversation <span>↗</span></a>`;$('#brand-showroom').innerHTML=`<img src="assets/${b.showroom}" alt="${escapeHTML(b.name+' showroom from the client brief')}"><span>FROM THE SHOWROOM COLLECTION · CLIENT BRIEF</span>`;$('#brand-vehicles').innerHTML=D.vehicles.filter(v=>v.brand===id).map(vehicleCard).join('');$$('[data-brand-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.brandView===id)));document.title=`${b.name} | SK Group`;syncCompare();}$$('[data-brand-view]').forEach(button=>button.addEventListener('click',()=>{render(button.dataset.brandView);const url=new URL(location.href);url.searchParams.set('brand',button.dataset.brandView);history.replaceState(null,'',url); }));render(id);}
function renderSaved(){const grid=$('#saved-grid');if(!grid)return;grid.innerHTML=savedIds.map(vehicleFor).filter(Boolean).map(vehicleCard).join('');$('.saved-empty').hidden=!!savedIds.length;syncCompare();}

function branchCard(s){const b=brandFor(s.brand);return `<article class="showroom-card"><div class="showroom-card-image"><img src="assets/${s.image}" alt="${escapeHTML(s.name+' showroom photograph; branch photo not independently assigned')}" loading="lazy"><span class="branch-badge">${s.verified?'PUBLIC DIRECTORY CONTACT':'CLIENT BRIEF'}</span></div><div class="showroom-card-copy"><p class="eyebrow">${escapeHTML(b.name.toUpperCase())}</p><h2>${escapeHTML(s.name)}<span>${escapeHTML(s.town)}</span></h2><p>${escapeHTML(s.address)}</p><div class="branch-actions"><button class="plain-link" type="button" data-branch-detail="${s.id}">View branch ↗</button>${s.verified?`<a href="tel:${s.phone}">Call showroom ↗</a>`:`<a href="book.html?type=enquiry&brand=${s.brand}">Enquire ↗</a>`}</div></div></article>`;}
function showBranch(id){const s=D.showrooms.find(x=>x.id===id);if(!s)return;const b=brandFor(s.brand);$('#detail-content').innerHTML=`<div class="detail-hero"><img src="assets/${s.image}" alt="${escapeHTML(s.name+' showroom photograph from the brief')}"></div><div class="detail-copy"><p class="eyebrow">${escapeHTML(b.name.toUpperCase())} / ${s.verified?'PUBLIC DIRECTORY CONTACT':'CLIENT BRIEF'}</p><h2 id="detail-title">${escapeHTML(s.name)} · ${escapeHTML(s.town)}</h2><p>${escapeHTML(s.address)}</p><div class="detail-actions">${s.verified?`<a class="button" href="tel:${s.phone}">Call showroom <span>↗</span></a><a class="button secondary" href="${s.maps}" target="_blank" rel="noopener">Get directions <span>↗</span></a>`:`<a class="button" href="book.html?type=enquiry&brand=${s.brand}">Ask about this branch <span>↗</span></a>`}<a class="text-link" href="book.html?type=test-ride&brand=${s.brand}">Preview a visit request ↗</a></div><p class="detail-notice">${s.verified?'Contact details are from the official Royal Enfield directory. Please confirm visiting hours directly. Photographs are not assigned to an individual GS Auto branch.':'The photograph and brand name follow the client brief. Confirmed address, telephone and visiting hours will be added before official use.'}</p></div>`;openDialog($('#detail-dialog'));}
function initShowrooms(){const grid=$('#showroom-grid');if(!grid)return;const search=$('#showroom-search'),brand=$('#showroom-brand');const params=new URLSearchParams(location.search);if(brandFor(params.get('brand')))brand.value=params.get('brand');function render(){const tokens=search.value.trim().toLowerCase().split(/\s+/).filter(Boolean);const list=D.showrooms.filter(s=>(brand.value==='all'||s.brand===brand.value)&&tokens.every(t=>`${s.name} ${s.town} ${brandFor(s.brand).name} ${s.address}`.toLowerCase().includes(t)));grid.innerHTML=list.map(branchCard).join('');$('.directory-count').textContent=`${list.length} ${list.length===1?'location':'locations'}`;$('#showroom-empty').hidden=!!list.length;}search.addEventListener('input',render);brand.addEventListener('change',render);render();}

function initCalculators(){if(!$('#emi-tool'))return;const ids=['loan-amount','loan-rate','loan-months'];function emi(){const [amount,rate,months]=ids.map(id=>Number($('#'+id).value));const valid=ids.every(id=>$('#'+id).checkValidity())&&Number.isInteger(months);if(!valid){['emi-value','principal-value','interest-value','total-value'].forEach(id=>$('#'+id).textContent='—');return;}const r=rate/1200;const monthly=r===0?amount/months:amount*r*Math.pow(1+r,months)/(Math.pow(1+r,months)-1);const total=monthly*months;$('#emi-value').textContent=money(monthly);$('#principal-value').textContent=money(amount);$('#interest-value').textContent=money(Math.max(0,total-amount));$('#total-value').textContent=money(total);}ids.forEach(id=>$('#'+id).addEventListener('input',emi));emi();const evIds=['ev-distance','ice-cost','electric-cost'];function ev(){const [distance,current,alternative]=evIds.map(id=>Number($('#'+id).value));const valid=evIds.every(id=>$('#'+id).checkValidity());$('#ev-saving').textContent=valid?money(distance*(current-alternative)):'—';$('#ice-annual').textContent=valid?money(distance*current):'—';$('#ev-annual').textContent=valid?money(distance*alternative):'—';}evIds.forEach(id=>$('#'+id).addEventListener('input',ev));ev();$$('[data-tool]').forEach(button=>button.addEventListener('click',()=>{$$('[data-tool]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$('#emi-tool').hidden=button.dataset.tool!=='emi';$('#ev-tool').hidden=button.dataset.tool!=='ev';}));}

function initRequest(){const form=$('#request-form');if(!form)return;const steps=$$('[data-step]',form),next=$('#wizard-next'),back=$('#wizard-back'),submit=$('#wizard-submit'),brand=$('#request-brand'),vehicle=$('#request-vehicle'),branch=$('#request-branch');let step=0;const names={'test-ride':'Test-ride request',service:'Service request',fleet:'Fleet enquiry',enquiry:'Conversation / callback',parts:'Parts & accessories',partner:'Business partnership'};const params=new URLSearchParams(location.search);const initialVehicle=vehicleFor(params.get('vehicle'));if(names[params.get('type')])$(`input[name="purpose"][value="${params.get('type')}"]`,form).checked=true;if(initialVehicle)brand.value=initialVehicle.brand;else if(brandFor(params.get('brand')))brand.value=params.get('brand');function options(){const list=D.vehicles.filter(v=>v.brand===brand.value);vehicle.innerHTML='<option value="">Help me choose</option>'+list.map(v=>`<option value="${v.id}">${escapeHTML(v.name)}</option>`).join('');const branches=D.showrooms.filter(s=>s.brand===brand.value);branch.innerHTML='<option value="">Help me find the right branch</option>'+branches.map(s=>`<option value="${s.id}">${escapeHTML(s.name+' · '+s.town+(s.verified?'':' (client brief)'))}</option>`).join('');}options();if(initialVehicle)vehicle.value=initialVehicle.id;brand.addEventListener('change',options);const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const part=t=>parts.find(p=>p.type===t).value;$('#request-date').min=`${part('year')}-${part('month')}-${part('day')}`;function purpose(){return $('input[name="purpose"]:checked',form).value;}function visit(){const required=['test-ride','service'].includes(purpose());$$('.visit-field',form).forEach(el=>el.hidden=!required);$('#request-date').required=required;if(!required){$('#request-date').value='';$('select[name="time"]',form).value='';}}$$('input[name="purpose"]',form).forEach(input=>input.addEventListener('change',visit));visit();function formData(){const f=new FormData(form);return Object.fromEntries(f.entries());}function review(){const data=formData(),b=brandFor(data.brand),v=vehicleFor(data.vehicle),s=D.showrooms.find(x=>x.id===data.branch);const fields=[['Request',names[data.purpose]],['Brand',b?.name||'Help me choose'],['Vehicle',v?.name||'Help me choose'],['Branch',s?`${s.name} · ${s.town}`:'Help me find the right branch']];if(data.date)fields.push(['Preferred date',data.date]);if(data.time)fields.push(['Preferred time',data.time]);fields.push(['Name',data.name],['Mobile',data.phone],['Town / city',data.city]);if(data.email)fields.push(['Email',data.email]);if(data.message)fields.push(['Note',data.message]);$('#request-review').innerHTML=fields.map(([label,value])=>`<div><span>${escapeHTML(label)}</span><span>${escapeHTML(value)}</span></div>`).join('');return data;}function showStep(scroll=false){steps.forEach((el,i)=>el.hidden=i!==step);$$('[data-step-marker]').forEach(el=>el.classList.toggle('active',Number(el.dataset.stepMarker)<=step));back.hidden=step===0;next.hidden=step===3;submit.hidden=step!==3;if(step===3)review();if(scroll)steps[step].querySelector('legend').scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth',block:'start'});}function validStep(){for(const field of $$('input,select,textarea',steps[step])){if(!field.checkValidity()){field.reportValidity();return false;}}return true;}next.addEventListener('click',()=>{if(!validStep())return;step=Math.min(3,step+1);showStep(true);});back.addEventListener('click',()=>{step=Math.max(0,step-1);showStep(true);});form.addEventListener('submit',event=>{event.preventDefault();if(step!==3||!form.reportValidity())return;const data=review();form.hidden=true;$('.wizard-progress').hidden=true;$('#request-success').hidden=false;const b=brandFor(data.brand),v=vehicleFor(data.vehicle);$('#success-summary').innerHTML=`<b>${escapeHTML(names[data.purpose])}</b><br>${escapeHTML(b?.name||'Brand to be discussed')} · ${escapeHTML(v?.name||'Vehicle to be discussed')}<br><span class="muted">${escapeHTML(data.city)} · Local preview only</span>`;$('#request-success').setAttribute('tabindex','-1');$('#request-success').focus();});$('#request-again').addEventListener('click',()=>{form.reset();form.hidden=false;$('.wizard-progress').hidden=false;$('#request-success').hidden=true;brand.value='';options();visit();step=0;showStep(true);});showStep();form.inert=false;}

function initFeatures(){const host=$('#feature-groups');if(!host)return;const search=$('#feature-search'),status=$('#feature-status');function render(){const q=search.value.trim().toLowerCase();const list=D.features.filter(f=>(status.value==='all'||f.status===status.value)&&`${f.name} ${f.group}`.toLowerCase().includes(q));const groups=[...new Set(list.map(f=>f.group))];host.innerHTML=groups.map(group=>{const items=list.filter(f=>f.group===group);return `<section class="feature-group"><header><h2>${escapeHTML(group)}</h2><span>${items.length} ${items.length===1?'idea':'ideas'}</span></header><div class="feature-list">${items.map(f=>`<div class="feature-row"><span>${String(f.id).padStart(3,'0')}</span><span>${escapeHTML(f.name)}</span><span class="phase-badge ${f.status==='Later phase'?'later':''}">${f.status==='UI preview'?'UI PREVIEW':'LATER PHASE'}</span></div>`).join('')}</div></section>`;}).join('')||'<p class="empty-state">No matching ideas. Try another search.</p>';$('#feature-count').textContent=`${list.length} of 120 features`;}search.addEventListener('input',render);status.addEventListener('change',render);render();}

const leadStages=['New','In conversation','Visit planned','Completed'];
const leads=[{id:1,vehicle:'himalayan',type:'Test ride',branch:'Howly',stage:0},{id:2,vehicle:'ronin',type:'Model enquiry',branch:'Group team',stage:0},{id:3,vehicle:'supercargo',type:'Fleet enquiry',branch:'Group team',stage:1},{id:4,vehicle:'r15',type:'Test ride',branch:'Dudhnoi',stage:1},{id:5,vehicle:'classic',type:'Service enquiry',branch:'Sonkuchi',stage:2},{id:6,vehicle:'badadost',type:'Fleet enquiry',branch:'Group team',stage:2},{id:7,vehicle:'superauto',type:'Callback',branch:'Group team',stage:3},{id:8,vehicle:'himalayan',type:'Model enquiry',branch:'Howly',stage:3}];
function leadDetail(id){const lead=leads.find(l=>l.id===Number(id));if(!lead)return;const v=vehicleFor(lead.vehicle);$('#lead-content').innerHTML=`<p class="eyebrow">SAMPLE RECORD · NO CUSTOMER DATA</p><h2 id="lead-title">Demo enquiry ${String(lead.id).padStart(2,'0')}</h2><p>This record is part of the frontend demonstration. It is not a real customer enquiry.</p><div class="lead-detail-list"><div><span>Interest</span><span>${escapeHTML(v.name)}</span></div><div><span>Brand</span><span>${escapeHTML(brandFor(v.brand).name)}</span></div><div><span>Request</span><span>${escapeHTML(lead.type)}</span></div><div><span>Branch</span><span>${escapeHTML(lead.branch)}</span></div><div><span>Stage</span><span>${leadStages[lead.stage]}</span></div></div>`;openDialog($('#lead-dialog'));}
function initStudio(){const board=$('#lead-board');if(!board)return;const search=$('#lead-search');function render(){const q=search.value.toLowerCase().trim();const filtered=leads.filter(l=>`Demo enquiry ${String(l.id).padStart(2,'0')} ${vehicleFor(l.vehicle).name} ${l.type} ${l.branch}`.toLowerCase().includes(q));$('#studio-stats').innerHTML=[['All sample enquiries',leads.length],['New conversations',leads.filter(l=>l.stage===0).length],['Visits planned',leads.filter(l=>l.stage===2).length],['Completed',leads.filter(l=>l.stage===3).length]].map(([label,value])=>`<article class="studio-stat"><span>${label}</span><strong>${String(value).padStart(2,'0')}</strong><small>Sample UI records</small></article>`).join('');board.innerHTML=leadStages.map((stage,index)=>{const list=filtered.filter(l=>l.stage===index);return `<section class="lead-column"><header><b>${stage}</b><span>${list.length}</span></header>${list.map(l=>`<article class="lead-card" data-lead-id="${l.id}"><p class="eyebrow">DEMO ENQUIRY ${String(l.id).padStart(2,'0')}</p><h3>${escapeHTML(vehicleFor(l.vehicle).name)}</h3><p>${escapeHTML(l.type)}<br>${escapeHTML(l.branch)}</p><button class="plain-link" type="button" data-lead-detail="${l.id}">View sample details ↗</button><label>Move to stage<select data-lead-stage="${l.id}" aria-label="Stage for demo enquiry ${l.id}">${leadStages.map((s,i)=>`<option value="${i}" ${i===l.stage?'selected':''}>${s}</option>`).join('')}</select></label></article>`).join('')}</section>`;}).join('');}search.addEventListener('input',render);board.addEventListener('change',event=>{const select=event.target.closest('[data-lead-stage]');if(!select)return;const lead=leads.find(l=>l.id===Number(select.dataset.leadStage));const next=Number(select.value);if(lead&&next>=0&&next<leadStages.length){lead.stage=next;render();toast('Sample stage updated for this UI preview.');}});board.addEventListener('click',event=>{const button=event.target.closest('[data-lead-detail]');if(button)leadDetail(button.dataset.leadDetail);});render();}

if($('#home-vehicles')){$('#home-vehicles').innerHTML=['himalayan','ronin','r15','superauto','supercargo','badadost'].map(vehicleFor).map(vehicleCard).join('');}
initCatalog();initBrand();initShowrooms();initCalculators();initRequest();initFeatures();initStudio();renderSaved();syncSaved();syncCompare();
